package com.bank.spark.model;

// A proposed bucketing plan to validate.
public class BucketPlan {
    private final String column;
    private final long distinctValues;    // cardinality
    private final boolean isJoinOrGroupKey;
    private final int numBuckets;
    private final boolean usesSaveAsTable;
    private final boolean deltaTable;

    public BucketPlan(String column, long distinctValues, boolean isJoinOrGroupKey,
                      int numBuckets, boolean usesSaveAsTable, boolean deltaTable) {
        this.column = column;
        this.distinctValues = distinctValues;
        this.isJoinOrGroupKey = isJoinOrGroupKey;
        this.numBuckets = numBuckets;
        this.usesSaveAsTable = usesSaveAsTable;
        this.deltaTable = deltaTable;
    }

    public String getColumn() { return column; }
    public long getDistinctValues() { return distinctValues; }
    public boolean isJoinOrGroupKey() { return isJoinOrGroupKey; }
    public int getNumBuckets() { return numBuckets; }
    public boolean usesSaveAsTable() { return usesSaveAsTable; }
    public boolean isDeltaTable() { return deltaTable; }
}
