package com.bank.spark.service;

import com.bank.spark.model.BucketPlan;

import java.util.ArrayList;
import java.util.List;

// Validates a bucketing plan against the requirements and caveats.
public class BucketPlanValidator {

    private static final long MIN_CARDINALITY = 10_000;

    // Returns a list of problems; empty means the plan is sound.
    public List<String> validate(BucketPlan p) {
        List<String> problems = new ArrayList<>();

        if (p.isDeltaTable()) {
            problems.add("Delta table: classic bucketing NOT supported — use OPTIMIZE + ZORDER/clustering");
        }
        if (p.getDistinctValues() < MIN_CARDINALITY) {
            problems.add("Low cardinality (" + p.getDistinctValues()
                    + "): hashing will not distribute evenly — bucket a high-cardinality key");
        }
        if (!p.isJoinOrGroupKey()) {
            problems.add("'" + p.getColumn() + "' is not a join/group key — bucketing buys nothing");
        }
        if (!p.usesSaveAsTable()) {
            problems.add("Raw path write: bucket metadata not registered — read will shuffle anyway, use saveAsTable");
        }
        if (p.getNumBuckets() < 1 || p.getNumBuckets() > 100_000) {
            problems.add("Bucket count " + p.getNumBuckets() + " looks wrong — size to cluster cores / ~hundreds of MB per bucket");
        }
        return problems;
    }
}
