package com.bank.spark;

import com.bank.spark.model.BucketPlan;
import com.bank.spark.service.BucketPlanValidator;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class BucketValidationDemo {

    private static final Logger log = Logger.getLogger(BucketValidationDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        BucketPlanValidator validator = new BucketPlanValidator();

        // Case A: good plan — account id, high card, join key, saveAsTable, parquet.
        BucketPlan good = new BucketPlan("accountId", 10_000_000L, true, 256, true, false);
        report(validator, "GOOD plan (accountId)", good);

        // Case B: branch — low cardinality mistake.
        BucketPlan lowCard = new BucketPlan("branch", 500L, true, 256, true, false);
        report(validator, "Branch (low cardinality)", lowCard);

        // Case C: account id but raw path write — catalog caveat.
        BucketPlan rawPath = new BucketPlan("accountId", 10_000_000L, true, 256, false, false);
        report(validator, "accountId via raw path", rawPath);

        // Case D: Delta table — not supported.
        BucketPlan delta = new BucketPlan("accountId", 10_000_000L, true, 256, true, true);
        report(validator, "accountId on Delta table", delta);
    }

    private static void report(BucketPlanValidator v, String label, BucketPlan plan) {
        List<String> problems = v.validate(plan);
        if (problems.isEmpty()) {
            log.info("[" + label + "] VALID — safe to bucket");
        } else {
            log.warning("[" + label + "] has " + problems.size() + " problem(s):");
            problems.forEach(pr -> log.warning("   - " + pr));
        }
    }
}

